using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Globalization;
using System.Net;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Web.Script.Serialization;
public sealed class InstructionData {public bool enabled=true;public Dictionary<string,string> sources=new Dictionary<string,string>();public Dictionary<string,string> cursors=new Dictionary<string,string>();}
internal sealed class QuestInstruction {internal string GuideSlug,GuideTitle,QuestName,GameQuestId,StepId,Key,Details,Coordinates,Url,Map,Credit;internal int Order;}
internal sealed class QuestInstructionIndex {
 internal readonly List<QuestInstruction> Items=new List<QuestInstruction>();internal int Guides,Unreadable;
 internal static string NameKey(string text){var s=WebUtility.HtmlDecode(text??"").Normalize(NormalizationForm.FormD);var b=new StringBuilder();foreach(char c in s){var type=CharUnicodeInfo.GetUnicodeCategory(c);if(type==UnicodeCategory.NonSpacingMark)continue;if(Char.IsLetterOrDigit(c))b.Append(Char.ToLowerInvariant(c));}return b.ToString().Replace("œ","oe").Replace("æ","ae");}
 internal static string Attribute(string tag,string name){var m=Regex.Match(tag,@"(?:\s|^)"+Regex.Escape(name)+@"\s*=\s*(?:""([^""]*)""|'([^']*)')",RegexOptions.IgnoreCase,TimeSpan.FromSeconds(1));return m.Success?WebUtility.HtmlDecode(m.Groups[1].Success?m.Groups[1].Value:m.Groups[2].Value):"";}
 internal static void Validate(Data data){if(data.instructions==null)data.instructions=new InstructionData();var d=data.instructions;if(d.sources==null)d.sources=new Dictionary<string,string>();if(d.cursors==null)d.cursors=new Dictionary<string,string>();if(d.sources.Count>3000||d.cursors.Count>5000||d.sources.Any(p=>p.Key.Length>300||!GanymedeReader.IsGuide(p.Value))||d.cursors.Any(p=>p.Key.Length>100||p.Value==null||p.Value.Length>100))throw new InvalidDataException("Réglages des instructions invalides.");}
 internal static QuestInstructionIndex Load(Store store){var index=new QuestInstructionIndex();string folder=Path.Combine(store.Root,"TougliCache");if(!Directory.Exists(folder))return index;foreach(var file in Directory.EnumerateFiles(folder,"ganymede-*.json").Take(200)){try{string slug=Path.GetFileNameWithoutExtension(file);if(!GanymedeReader.IsGuide(slug)||new FileInfo(file).Length>TougliReader.MaxBytes)continue;index.Add(File.ReadAllText(file),slug);}catch{index.Unreadable++;}}return index;}
 internal void Add(string json,string slug){var doc=GanymedeReader.Parse(json,slug);var serializer=new JavaScriptSerializer{MaxJsonLength=TougliReader.MaxBytes,RecursionLimit=64};var guide=TougliReader.Get(serializer.DeserializeObject(json),"ganymedeGuide");var staged=new List<QuestInstruction>();int page=0;foreach(var step in TougliReader.Arr(TougliReader.Get(guide,"steps")).OrderBy(s=>Convert.ToInt32(TougliReader.Get(s,"order")??0))){page++;string html=TougliReader.S(TougliReader.Get(step,"text"));if(html.Length>200000)continue;var stack=new Stack<Tuple<string,int,int>>();foreach(Match token in Regex.Matches(html,@"<div\b[^>]*>|</div\s*>",RegexOptions.IgnoreCase,TimeSpan.FromSeconds(2))){if(!token.Value.StartsWith("</",StringComparison.Ordinal)){string name=Attribute(token.Value,"data-type")=="quest-block"?(Attribute(token.Value,"questname")!=""?Attribute(token.Value,"questname"):Attribute(token.Value,"title")):"";stack.Push(Tuple.Create(name,token.Index+token.Length,token.Index));}else if(stack.Count>0){var open=stack.Pop();if(open.Item1=="")continue;string content=html.Substring(open.Item2,token.Index-open.Item2);string text=GanymedeReader.Instructions(content);if(text=="")continue;string id=TougliReader.S(TougliReader.Get(step,"id"));string gameId="";foreach(Match tag in Regex.Matches(content,@"<span\b[^>]*>",RegexOptions.IgnoreCase,TimeSpan.FromSeconds(2))){if(Attribute(tag.Value,"type")=="quest"&&NameKey(Attribute(tag.Value,"name"))==NameKey(open.Item1)){string candidate=Attribute(tag.Value,"dofusdbid");if(Regex.IsMatch(candidate,@"^[1-9][0-9]{0,8}$"))gameId=candidate;}}
 var entry=new QuestInstruction{GuideSlug=slug,GuideTitle=doc.Title,Credit=GanymedeReader.Credit(doc),QuestName=open.Item1,GameQuestId=gameId,StepId=id,Order=page,Details=text,Map=TougliReader.Plain(TougliReader.Get(step,"map")),Url=GanymedeReader.Url(slug)+"?page="+page+"&stepsPerPage=1"};var source=doc.Steps.FirstOrDefault(s=>s.Url==entry.Url);entry.Coordinates=source==null?"":source.Coordinates;entry.Key=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(slug+"/"+id+"/"+NameKey(open.Item1)+"/"+text));staged.Add(entry);}}}Items.RemoveAll(x=>x.GuideSlug==slug);Items.AddRange(staged.GroupBy(x=>x.Key).Select(g=>g.First()));Guides++;}
 internal List<QuestInstruction> Match(TougliStep step){if(step==null||String.IsNullOrWhiteSpace(step.QuestId))return new List<QuestInstruction>();string name=NameKey(step.Title);return Items.Where(x=>NameKey(x.QuestName)==name&&(x.GameQuestId==""||x.GameQuestId==step.QuestId)).OrderBy(x=>x.GuideTitle).ThenBy(x=>x.Order).ToList();}
 internal static string CursorKey(Data data,TougliStep step,string guide){var c=DofusCompanion.Character(data);return WorkspaceNext.Hash(Encoding.UTF8.GetBytes((c==null?"":c.id)+"/"+(c==null?"":c.guide)+"/"+step.Key+"/"+guide));}
}
